/**
 * Restauración exacta del DOM. Regla del contrato: `destroy()` deja el
 * elemento como estaba antes de montar (atributos, estilos inline, texto e
 * hijos), así un remount de React StrictMode no acumula restos.
 */

export type Restore = () => void;

export interface PreserveOptions {
  /** Atributos que el efecto puede tocar (se guardan, incluida su ausencia). */
  attributes?: string[];
  /** Propiedades de estilo inline que el efecto puede tocar (`transform`, `--p`…). */
  styles?: string[];
  /** Guarda y restaura los hijos tal cual (para efectos que reescriben el contenido). */
  children?: boolean;
}

/** Toma una foto del estado del elemento y devuelve la función que lo repone. */
export function preserve(el: Element, { attributes = [], styles = [], children = false }: PreserveOptions): Restore {
  const attrs = attributes.map((name) => [name, el.getAttribute(name)] as const);
  const style = (el as HTMLElement).style as CSSStyleDeclaration | undefined;
  const inline = styles.map((prop) => [prop, style?.getPropertyValue(prop) ?? '', style?.getPropertyPriority(prop) ?? ''] as const);
  const kids = children ? Array.from(el.childNodes) : null;
  const styleAttr = styles.length ? el.getAttribute('style') : null;
  const cssTextBefore = styles.length ? (style?.cssText ?? '') : '';

  return () => {
    for (const [name, value] of attrs) {
      if (value === null) el.removeAttribute(name);
      else el.setAttribute(name, value);
    }
    for (const [prop, value, priority] of inline) {
      if (!style) break;
      if (value) style.setProperty(prop, value, priority);
      else style.removeProperty(prop);
    }
    // Si el estilo quedó igual al de antes, se repone el atributo textual tal
    // cual estaba (el navegador lo normaliza al escribir propiedades).
    if (styles.length && style && style.cssText === cssTextBefore) {
      if (styleAttr === null) el.removeAttribute('style');
      else el.setAttribute('style', styleAttr);
    }
    if (kids) el.replaceChildren(...kids);
  };
}

/** Une varias funciones de limpieza en una, en orden inverso al de montaje. */
export function bundle(...fns: Array<(() => void) | undefined | null | false>): () => void {
  return () => {
    for (let i = fns.length - 1; i >= 0; i--) {
      const fn = fns[i];
      if (fn) fn();
    }
  };
}

/** Busca un hijo por atributo `data-fx-*` dentro del efecto. */
export const part = <T extends Element = HTMLElement>(root: ParentNode, name: string): T | null =>
  root.querySelector<T>(`[data-fx-${name}]`);

export const parts = <T extends Element = HTMLElement>(root: ParentNode, name: string): T[] =>
  Array.from(root.querySelectorAll<T>(`[data-fx-${name}]`));

export * from './math';
export * from './motion';
export * from './dom';
export * from './loop';
export * from './tokens';
export * from './types';

/**
 * Un loop de rAF que se puede prender y apagar, con `dt` en segundos (con tope
 * para que una pestaña que vuelve de segundo plano no dé un salto).
 * `tick` devuelve `false` para dormirse; `wake()` lo vuelve a prender.
 */
export interface Loop {
  wake(): void;
  stop(): void;
  readonly running: boolean;
}

export function createLoop(tick: (dt: number, now: number) => boolean | void, maxDt = 0.1): Loop {
  let raf = 0;
  let last = 0;
  const frame = (now: number) => {
    const dt = last ? Math.min(maxDt, (now - last) / 1000) : 1 / 60;
    last = now;
    const keep = tick(dt, now);
    raf = keep === false ? 0 : requestAnimationFrame(frame);
  };
  return {
    wake() {
      if (raf) return;
      last = 0;
      raf = requestAnimationFrame(frame);
    },
    stop() {
      cancelAnimationFrame(raf);
      raf = 0;
    },
    get running() {
      return raf !== 0;
    },
  };
}

/** Utilidades numéricas compartidas por todos los efectos. */

export const clamp = (n: number, min: number, max: number): number => Math.min(max, Math.max(min, n));

export const clamp01 = (n: number): number => clamp(n, 0, 1);

export const lerp = (a: number, b: number, t: number): number => a + (b - a) * t;

/** Lleva `value` del rango [inMin, inMax] al rango [0, 1], recortado. */
export const progress = (value: number, inMin: number, inMax: number): number =>
  clamp01((value - inMin) / Math.max(1e-9, inMax - inMin));

/**
 * Suavizado exponencial independiente del frame rate: el valor se acerca al
 * objetivo con la misma sensación a 30, 60 o 120 fps. `retain` es la fracción
 * que queda por recorrer después de un segundo (0.0015 ≈ planea, 0.05 ≈ rápido).
 */
export const damp = (current: number, target: number, retain: number, dt: number): number =>
  lerp(current, target, 1 - Math.pow(retain, dt));

/**
 * Reduced motion y visibilidad, con el mismo comportamiento en todos los efectos.
 *
 * `motionSwitch` es la pieza central del contrato: cada efecto declara cómo se
 * monta con movimiento (`full`) y cómo queda quieto (`reduced`), y el switch
 * cambia de uno a otro en vivo si la persona cambia la preferencia del sistema
 * sin recargar la página.
 */

const REDUCE = '(prefers-reduced-motion: reduce)';

export type Teardown = () => void;

const media = (query: string): MediaQueryList | null =>
  typeof window !== 'undefined' && typeof window.matchMedia === 'function' ? window.matchMedia(query) : null;

export const prefersReducedMotion = (): boolean => media(REDUCE)?.matches ?? false;

/**
 * Monta `full` o `reduced` según la preferencia y cambia en vivo.
 * Cada rama devuelve su propio teardown. Devuelve el teardown total.
 */
export function motionSwitch(branches: { full: () => Teardown | void; reduced?: () => Teardown | void }): Teardown {
  const mq = media(REDUCE);
  let current: Teardown | void;
  const mount = () => {
    current?.();
    current = mq?.matches ? branches.reduced?.() : branches.full();
  };
  mount();
  mq?.addEventListener('change', mount);
  return () => {
    mq?.removeEventListener('change', mount);
    current?.();
    current = undefined;
  };
}

/**
 * Llama a `onChange(true|false)` cuando el elemento entra o sale de la
 * pantalla. Sirve para pausar loops y rAF fuera de vista.
 */
export function onVisibility(el: Element, onChange: (visible: boolean) => void, rootMargin = '0px'): Teardown {
  if (typeof IntersectionObserver === 'undefined') {
    onChange(true);
    return () => {};
  }
  const io = new IntersectionObserver((entries) => {
    const entry = entries[entries.length - 1];
    if (entry) onChange(entry.isIntersecting);
  }, { rootMargin });
  io.observe(el);
  return () => io.disconnect();
}

/**
 * Llama a `cb` una sola vez, cuando el elemento queda a `margin` de la
 * pantalla (por defecto una pantalla). Para cargar dependencias o assets
 * pesados recién cuando hacen falta.
 */
export function whenNear(el: Element, cb: () => void, margin = '100% 0px'): Teardown {
  if (typeof IntersectionObserver === 'undefined') {
    cb();
    return () => {};
  }
  const io = new IntersectionObserver((entries) => {
    if (!entries.some((e) => e.isIntersecting)) return;
    io.disconnect();
    cb();
  }, { rootMargin: margin });
  io.observe(el);
  return () => io.disconnect();
}

/** El puntero es fino (mouse o trackpad): para efectos de cursor y hover. */
export const finePointer = (): boolean => media('(hover: hover) and (pointer: fine)')?.matches ?? false;

'use client';

import { useEffect, useRef, type DependencyList, type RefObject } from 'react';
import type { FxHandle } from './types';

/**
 * Monta un efecto sobre `ref.current` y lo destruye al desmontar o cuando
 * cambian las dependencias. Sobrevive StrictMode porque todo `destroy()` del
 * kit deja el DOM como estaba.
 *
 *   const ref = useRef<HTMLDivElement>(null);
 *   useFx(ref, (el) => createCountUp(el, { locale: 'es-AR' }), []);
 *
 * Devuelve una ref al handle actual, para llamar a su API (`set`, `setLight`…).
 */
export function useFx<E extends HTMLElement, H extends FxHandle>(
  ref: RefObject<E | null>,
  create: (el: E) => H | null | undefined,
  deps: DependencyList = [],
): RefObject<H | null> {
  const handle = useRef<H | null>(null);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const h = create(el) ?? null;
    handle.current = h;
    return () => {
      h?.destroy();
      if (handle.current === h) handle.current = null;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, deps);
  return handle;
}

/**
 * Tokens del kit. Los efectos nunca traen colores ni curvas propias: leen
 * variables `--fx-*` que el proyecto mapea a sus tokens una sola vez
 * (ver docs/CONTRACT.md):
 *
 *   :root {
 *     --fx-ground: var(--color-ground);
 *     --fx-ink: var(--color-ink);
 *     --fx-accent: var(--color-accent);
 *     --fx-ease: cubic-bezier(0.16, 1, 0.3, 1);
 *     --fx-duration: 900ms;
 *   }
 */

export const FX_TOKENS = ['--fx-ground', '--fx-ink', '--fx-muted', '--fx-accent', '--fx-on-accent', '--fx-ease', '--fx-duration'] as const;

export type FxToken = (typeof FX_TOKENS)[number] | `--fx-${string}`;

/** Lee un token resuelto desde el elemento (hereda del :root). */
export function token(el: Element, name: FxToken, fallback = ''): string {
  if (typeof getComputedStyle === 'undefined') return fallback;
  return getComputedStyle(el).getPropertyValue(name).trim() || fallback;
}

/** Duración del token en milisegundos (acepta `900ms` o `0.9s`). */
export function durationMs(el: Element, name: FxToken = '--fx-duration', fallback = 900): number {
  const raw = token(el, name);
  if (!raw) return fallback;
  const n = parseFloat(raw);
  if (Number.isNaN(n)) return fallback;
  return raw.endsWith('ms') ? n : n * 1000;
}

/** La curva del sitio como array para GSAP/Motion: `cubic-bezier(a,b,c,d)` → `[a,b,c,d]`. */
export function easeArray(el: Element, name: FxToken = '--fx-ease'): [number, number, number, number] {
  const m = token(el, name).match(/cubic-bezier\(([^)]+)\)/);
  const parts = m?.[1]?.split(',').map((s) => parseFloat(s));
  if (parts && parts.length === 4 && parts.every((n) => !Number.isNaN(n))) return parts as [number, number, number, number];
  return [0.16, 1, 0.3, 1]; // la curva de la casa (docs/SIGNATURE-OBLIVION.md)
}

/** Lo mínimo que devuelve todo efecto del kit. */
export interface FxHandle {
  /** Deja el DOM como estaba antes de montar y suelta listeners, observers, rAF y recursos. */
  destroy(): void;
}

/** Firma de todo efecto: un elemento raíz y opciones. */
export type FxFactory<O, H extends FxHandle = FxHandle> = (target: HTMLElement, options?: O) => H;
